order=sorted(fG,key=lambda c:(fG[c][0],fG[c][1]))
names=[fG[c][1] for c in order]; n=len(names)
TT,OO,S=matrix(order); H=4*max(s.count('[]') for s in names)+3
M=solve_all(TT,OO,S,H)
cc=((M==1)&(M.T==1)).sum(1)
