assert int(score[names.index('[]p')])==14158
print('WINNERS',[(names[a],int(score[a]),[int(v[a]) for v in (cc,cd,dc,dd)]) for a in w],flush=True)
print('FB',int(score[names.index('[]p')]),flush=True)
safe=cd==0
assert int(safe.sum())==1693
assert int((safe & np.diag(M).astype(bool)).sum())==517
for a in w:
    for b in range(n):
        assert game(names[a],names[b])==(bool(M[a,b]),bool(M[b,a]))
    for b in [a,names.index('F'),names.index('~F'),names.index('[]p')]:
        assert solve(names[a],names[b])==(bool(M[a,b]),bool(M[b,a]))
print('PASS safety counts, full winner rows independently re-solved and headline GLS certificates',flush=True)
